/**
 * The Reservation Files, as published on the web.
 *
 * reservation-files.js is generated by scripts/import-reservation-files.mjs
 * from the print-first HTML that also typesets the book, so it is never edited
 * by hand and the importer can be re-run at any time. Part 1's web edition is
 * a hand-written rewrite that exists only here — the printed part is
 * unchanged — so it is layered on top rather than merged into the generated
 * file.
 *
 * Everything except Part 1 passes through untouched. If a future part needs
 * the same treatment, add it to OVERRIDES.
 */
import parts from './reservation-files.js';
import webPartOne from './reservation-files-part-1.web.js';

const OVERRIDES = { 1: webPartOne };

export default parts.map((part) => OVERRIDES[part.n]?.(part) ?? part);
